-- Mapping owns separate state. Existing OCR rows and constraints remain untouched.
CREATE TABLE "CV_MAPPING_CONFIGS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "REVISION" VARCHAR(128) NOT NULL UNIQUE,
    "DEFINITION" JSONB NOT NULL CHECK (jsonb_typeof("DEFINITION")='object'),
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ACTIVATED_AT" TIMESTAMPTZ,
    "CONTENT_SHA256" CHAR(64),
    "VALIDATION_STATE" VARCHAR(10) NOT NULL DEFAULT 'DRAFT'
        CHECK ("VALIDATION_STATE" IN ('DRAFT','TESTED','ACTIVE')),
    CONSTRAINT "CK_MAPPING_CONFIG_HASH" CHECK (
        "VALIDATION_STATE"='DRAFT' OR ("CONTENT_SHA256" IS NOT NULL AND "CONTENT_SHA256"::text ~ '^[0-9a-f]{64}$')),
    CONSTRAINT "CK_MAPPING_CONFIG_ACTIVE" CHECK (
        ("VALIDATION_STATE"='ACTIVE')=("ACTIVATED_AT" IS NOT NULL))
);
CREATE FUNCTION protect_mapping_config() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD."ACTIVATED_AT" IS NOT NULL THEN
        RAISE EXCEPTION 'Activated mapping configuration is immutable';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER "TR_MAPPING_CONFIG_IMMUTABLE" BEFORE UPDATE OR DELETE ON "CV_MAPPING_CONFIGS"
    FOR EACH ROW EXECUTE FUNCTION protect_mapping_config();

CREATE TABLE "CV_MAPPING_SETTINGS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK ("ID"=1),
    "ACTIVE_CONFIG_ID" BIGINT REFERENCES "CV_MAPPING_CONFIGS" ("ID"),
    "SCAN_AFTER_ID" BIGINT NOT NULL DEFAULT 0 CHECK ("SCAN_AFTER_ID">=0),
    "SCAN_UPPER_ID" BIGINT CHECK ("SCAN_UPPER_ID">=0)
);
INSERT INTO "CV_MAPPING_SETTINGS" ("ID") VALUES (1);

CREATE TABLE "CV_MAPPING_JOBS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EXTRACTION_ID" BIGINT NOT NULL REFERENCES "CV_EXTRACTIONS" ("ID"),
    "CONFIG_ID" BIGINT NOT NULL REFERENCES "CV_MAPPING_CONFIGS" ("ID"),
    "ENGINE_VERSION" VARCHAR(128) NOT NULL,
    "STATUS" VARCHAR(20) NOT NULL DEFAULT 'PENDING'
        CHECK ("STATUS" IN ('PENDING','PROCESSING','COMPLETED','FAILED')),
    "ATTEMPTS" INTEGER NOT NULL DEFAULT 0 CHECK ("ATTEMPTS" BETWEEN 0 AND 3),
    "TOKEN" UUID,
    "LEASE_EXPIRES_AT" TIMESTAMPTZ,
    "HARD_DEADLINE_AT" TIMESTAMPTZ,
    "INPUT_SHA256" CHAR(64) CHECK ("INPUT_SHA256" IS NULL OR "INPUT_SHA256"::text ~ '^[0-9a-f]{64}$'),
    "NEXT_ATTEMPT_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ERROR_CODE" VARCHAR(40),
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "COMPLETED_AT" TIMESTAMPTZ,
    CONSTRAINT "UQ_MAPPING_INPUT" UNIQUE ("EXTRACTION_ID","CONFIG_ID","ENGINE_VERSION"),
    CONSTRAINT "CK_MAPPING_LEASE" CHECK ("STATUS"<>'PROCESSING' OR
        ("TOKEN" IS NOT NULL AND "LEASE_EXPIRES_AT" IS NOT NULL AND "ATTEMPTS">0
            AND "HARD_DEADLINE_AT" IS NOT NULL AND "LEASE_EXPIRES_AT"<="HARD_DEADLINE_AT")),
    CONSTRAINT "CK_MAPPING_COMPLETED_INPUT" CHECK ("STATUS"<>'COMPLETED' OR "INPUT_SHA256" IS NOT NULL),
    CONSTRAINT "CK_MAPPING_TERMINAL" CHECK (("STATUS" IN ('COMPLETED','FAILED'))=("COMPLETED_AT" IS NOT NULL))
);
CREATE INDEX "IX_MAPPING_READY" ON "CV_MAPPING_JOBS" ("NEXT_ATTEMPT_AT","ID") WHERE "STATUS"='PENDING';
CREATE INDEX "IX_MAPPING_EXPIRY" ON "CV_MAPPING_JOBS" ("LEASE_EXPIRES_AT","ID") WHERE "STATUS"='PROCESSING';

CREATE TABLE "CV_MAPPING_RESULTS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "JOB_ID" BIGINT NOT NULL UNIQUE REFERENCES "CV_MAPPING_JOBS" ("ID"),
    "SCHEMA_VERSION" INTEGER NOT NULL CHECK ("SCHEMA_VERSION"=1),
    "QUALITY" VARCHAR(24) NOT NULL CHECK ("QUALITY" IN ('NEEDS_REVIEW','UNSUPPORTED_INPUT')),
    "DIGEST" CHAR(64) NOT NULL CHECK ("DIGEST"::text ~ '^[0-9a-f]{64}$'),
    "RESULT" JSONB NOT NULL CHECK (jsonb_typeof("RESULT")='object'),
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE FUNCTION protect_mapping_result() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Mapping results are immutable'; END;
$$;
CREATE TRIGGER "TR_MAPPING_RESULT_IMMUTABLE" BEFORE UPDATE OR DELETE ON "CV_MAPPING_RESULTS"
    FOR EACH ROW EXECUTE FUNCTION protect_mapping_result();
